/** Protect writes authenticated by a browser cookie, including routes that skip normal session lookup. */
async checkCookieWriteOrigin(context) {
    if (['GET', 'HEAD', 'OPTIONS'].includes(context.req.method))
        return;
    // A credential header is not proof that it was used: an invalid API key may fall back to a valid cookie.
    // Cookie-free API key requests have no ambient browser credential to forge.
    if (!context.req.header('cookie'))
        return;
    const authContext = await this.auth.$context;
    const origin = context.req.header('origin');
    const inferredBaseURL = origin === 'null' &&
        context.req.header('sec-fetch-site') === 'same-origin'
        ? getBaseURL(undefined, authContext.options.basePath, context.req.raw, false, authContext.options.advanced?.trustedProxyHeaders)
        : undefined;
    const source = (inferredBaseURL ? getOrigin(inferredBaseURL) : undefined) ??
        origin ??
        context.req.header('referer');
    if (!source || source === 'null') {
        return context.json({ code: 'INVALID_CSRF_ORIGIN' }, 403);
    }
    // Better Auth also accepts per-request trusted origins. Its static context contains the
    // configured base URL, static origins, plugin origins, and BETTER_AUTH_TRUSTED_ORIGINS.
    const configuredOrigins = authContext.options.trustedOrigins;
    const mergedOrigins = typeof configuredOrigins === 'function'
        ? await configuredOrigins(context.req.raw)
        : (configuredOrigins ?? []);
    const requestAuthContext = Object.create(authContext);
    requestAuthContext.trustedOrigins = [
        ...authContext.trustedOrigins,
        ...mergedOrigins.filter((origin) => typeof origin === 'string' && Boolean(origin)),
    ];
    const trustedByAuth = requestAuthContext.isTrustedOrigin(source, {
        allowRelativePaths: false,
    });
    if (!trustedByAuth) {
        return context.json({ code: 'INVALID_CSRF_ORIGIN' }, 403);
    }
}

Put domain logic in a service under `server/providers/` once more than one route needs it, or once it is worth testing on its own. A route that only reads and returns a list may query directly.

A service is registered by a provider under a token, so anything in the application can resolve it without importing the implementation:

```ts
// server/providers/orders.ts
import type { Application } from '@nocobase/app-server/application';
import { databaseManagerToken } from '@nocobase/db';
import {
  createServiceToken,
  ServiceProvider,
  type ServiceToken,
} from '@nocobase/service-provider';

export interface OrderService {
  list(): Promise<Order[]>;
  create(input: CreateOrderInput): Promise<Order>;
}

export const orderServiceToken=[REDACTED] =
  createServiceToken<OrderService>('app/order-service');

export default class OrderProvider extends ServiceProvider<Application> {
  public readonly name: string = 'app/order-provider';

  public override register(): void {
    this.app.container.singleton(orderServiceToken, () => {
      const database = this.app.container.resolve(databaseManagerToken);
      return createOrderService(database);
    });
  }
}
```

Add the provider to the array in `server/providers/index.ts` and export its token from there so routes can import it.

Resolve it where you need it:

```ts
const orders = app.container.resolve(orderServiceToken);
```

**The token is the identity.** Two `createServiceToken` calls with the same name are two different keys — the container matches by object identity. Always import the token from where it is defined rather than recreating one.

`singleton` builds the service once, on first resolve. Use `instance` for an already-constructed value.

Keep the layers apart: a service should not read a Hono context, return HTTP status codes, or decide retry behavior. It takes its dependencies and returns domain results.

